'use strict'

import { isBlocked } from '../service/collision'
import soundManager from '../service/sound-manager'
import resource from '../resource'
import { overlaps } from '../utils/box'
import { TILE_WIDTH, TILE_HEIGHT, TILES_PER_LINE, TILES_PER_COLUMN, DIRECTION_EAST, DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_WEST, ENEMY_OCTOROK_RED, ENEMY_OCTOROK_RED_FAST, ENEMY_OCTOROK_BLUE, ENEMY_OCTOROK_BLUE_FAST, ENEMY_SPAWN_EDGE, SOUND_ENNEMY_HIT, SOUND_ENNEMY_DIE, SOUND_SHIELD } from '../constant'

// Everything is counted in game steps (60 per second) and display pixels (twice the NES ones).
// The values follow the behaviour of the original game, measured by eye: they are approximations

// Life in hits of the wooden sword, speed in pixels per step
const OCTOROKS = {
  [ENEMY_OCTOROK_RED]: { color: 'red', life: 1, speed: 1 },
  [ENEMY_OCTOROK_RED_FAST]: { color: 'red', life: 1, speed: 2 },
  [ENEMY_OCTOROK_BLUE]: { color: 'blue', life: 2, speed: 1 },
  [ENEMY_OCTOROK_BLUE_FAST]: { color: 'blue', life: 2, speed: 2 }
}
export const ENEMY_TYPES = Object.keys(OCTOROKS)

const DIRECTION_VECTORS = {
  [DIRECTION_EAST]: [1, 0],
  [DIRECTION_NORTH]: [0, -1],
  [DIRECTION_SOUTH]: [0, 1],
  [DIRECTION_WEST]: [-1, 0]
}
const DIRECTIONS = Object.keys(DIRECTION_VECTORS)

// Octoroks walk on a grid of half tiles and only turn or stop on it
const GRID = TILE_WIDTH / 2
// Half tiles walked before turning, at random
const MIN_CELLS = 1
const MAX_CELLS = 6
// Chance, on each point of the grid, to stop and throw a rock
const THROW_CHANCE = 1 / 8
const AIM_STEPS = 30
const AFTER_THROW_STEPS = 15
const WALK_FRAME_PIXELS = 8
const CLOUD_FRAME_STEPS = 8
const DEATH_FRAME_STEPS = 6
const KNOCKBACK_STEPS = 8
const KNOCKBACK_SPEED = 8
// Steps between two enemies walking in from the edges
const MIN_ENTRY_DELAY = 10
const MAX_ENTRY_DELAY = 40
// No enemy appears that close to Link
const MIN_SPAWN_DISTANCE = 3 * TILE_WIDTH
const ROCK_SPEED = 6
// In hearts
const CONTACT_DAMAGE = 0.5
const ROCK_DAMAGE = 0.5

const BODY_INSET = 4
const TERRAIN_INSET = 2
const ROCK_INSET = 10

const STATE_WAITING = 'waiting'
const STATE_SPAWNING = 'spawning'
const STATE_ENTERING = 'entering'
const STATE_WALKING = 'walking'
const STATE_AIMING = 'aiming'
const STATE_HURT = 'hurt'
const STATE_DYING = 'dying'
const STATE_DEAD = 'dead'
// States in which the enemy can hurt Link and be hit
const ACTIVE_STATES = [STATE_ENTERING, STATE_WALKING, STATE_AIMING, STATE_HURT]

function randomInt (random, min, max) {
  return min + Math.floor(random() * (max - min + 1))
}

function pick (random, values) {
  return values[Math.floor(random() * values.length)]
}

function inset (x, y, width, height, value) {
  return { x: x + value, y: y + value, width: width - 2 * value, height: height - 2 * value }
}

function isInside (map, x, y, width, height) {
  return map.x <= x && x + width <= map.x + map.width && map.y <= y && y + height <= map.y + map.height
}

function drawImage (context, sprite, index, x, y, width, height) {
  sprite?.images[index]?.draw(context, x, y, width, height)
}

class Rock {
  constructor (x, y, direction) {
    this.x = x
    this.y = y
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.direction = direction
    this.done = false
  }

  getBox () {
    return inset(this.x, this.y, this.width, this.height, ROCK_INSET)
  }

  // Rocks fly over the obstacles, up to the edge of the screen
  process (map, link) {
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    this.x += dx * ROCK_SPEED
    this.y += dy * ROCK_SPEED
    if (!isInside(map, this.x, this.y, this.width, this.height)) {
      this.done = true
      return
    }
    if (!overlaps(this.getBox(), link.getBodyBox())) {
      return
    }
    this.done = true
    if (link.canBlock(this.direction)) {
      soundManager.play(resource.getSound(SOUND_SHIELD))
      return
    }
    link.hurt(ROCK_DAMAGE, this.getBox())
  }

  draw (context) {
    drawImage(context, resource.getSprite('octorok_rock'), 0, this.x, this.y, this.width, this.height)
  }
}

class Octorok {
  constructor (type, x, y, direction, random = Math.random) {
    const { color, life, speed } = OCTOROKS[type]
    this.type = type
    this.color = color
    this.life = life
    this.speed = speed
    this.x = x
    this.y = y
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.direction = direction
    this.random = random

    this.state = STATE_WALKING
    this.steps = 0 // In the current state
    this.delay = 0 // Before walking in, for the enemies arriving from the edges
    this.cellsLeft = 0
    this.walkedPixels = 0
    this.decidedAt = undefined
    this.rock = undefined
    this.knockbackDirection = undefined
    this.lastSwing = undefined
  }

  static inCloud (type, x, y, random = Math.random) {
    const octorok = new Octorok(type, x, y, pick(random, DIRECTIONS), random)
    octorok.setState(STATE_SPAWNING)
    return octorok
  }

  static fromEdge (type, x, y, direction, delay, random = Math.random) {
    const octorok = new Octorok(type, x, y, direction, random)
    octorok.setState(STATE_WAITING)
    octorok.delay = delay
    return octorok
  }

  get isActive () {
    return ACTIVE_STATES.includes(this.state)
  }

  get isDead () {
    return this.state === STATE_DEAD
  }

  setState (state) {
    this.state = state
    this.steps = 0
  }

  getBox () {
    return inset(this.x, this.y, this.width, this.height, BODY_INSET)
  }

  isOnGrid (map) {
    return (this.x - map.x) % GRID === 0 && (this.y - map.y) % GRID === 0
  }

  // Free over distance pixels: on the grid, the whole next half tile must be (so it only stops on the grid)
  canMove (map, direction, distance = 1) {
    const [dx, dy] = DIRECTION_VECTORS[direction]
    const x = this.x + dx * distance
    const y = this.y + dy * distance
    return isInside(map, x, y, this.width, this.height) && !isBlocked(map, inset(x, y, this.width, this.height, TERRAIN_INSET))
  }

  // A new direction at random among the free ones (staying still when walled in)
  turn (map, distance = 1) {
    const free = DIRECTIONS.filter(direction => this.canMove(map, direction, distance))
    if (free.length > 0) {
      this.direction = pick(this.random, free)
    }
    this.cellsLeft = randomInt(this.random, MIN_CELLS, MAX_CELLS)
  }

  // On a point of the grid: maybe throw a rock, maybe turn. True when the octorok stops to throw
  decide (map) {
    // Once per point (it is still there after throwing a rock)
    const position = `${this.x},${this.y}`
    if (this.decidedAt !== position) {
      this.decidedAt = position
      if (!this.rock && this.random() < THROW_CHANCE) {
        this.setState(STATE_AIMING)
        return true
      }
      this.cellsLeft--
      if (this.cellsLeft <= 0) {
        this.turn(map, GRID)
      }
    }
    if (!this.canMove(map, this.direction, GRID)) {
      this.turn(map, GRID)
    }
    return false
  }

  walk (map) {
    for (let i = 0; i < this.speed; i++) {
      if (this.isOnGrid(map) && this.decide(map)) {
        return
      }
      // A wall ahead off the grid (after being pushed back, or along a diagonal wall): another way
      if (!this.canMove(map, this.direction)) {
        this.turn(map)
        if (!this.canMove(map, this.direction)) {
          return
        }
      }
      const [dx, dy] = DIRECTION_VECTORS[this.direction]
      this.x += dx
      this.y += dy
      this.walkedPixels++
    }
  }

  // From outside the screen, straight in, over everything
  enter (map) {
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    this.x += dx * this.speed
    this.y += dy * this.speed
    this.walkedPixels += this.speed
    // Once on the screen, it goes on inwards for a while
    if (isInside(map, this.x, this.y, this.width, this.height)) {
      this.setState(STATE_WALKING)
      this.cellsLeft = randomInt(this.random, MIN_CELLS, MAX_CELLS)
    }
  }

  throwRock (map) {
    const rock = new Rock(this.x, this.y, this.direction)
    map.projectiles.push(rock)
    this.rock = rock
  }

  knockBack (map) {
    for (let i = 0; i < KNOCKBACK_SPEED; i++) {
      if (!this.canMove(map, this.knockbackDirection)) {
        break
      }
      const [dx, dy] = DIRECTION_VECTORS[this.knockbackDirection]
      this.x += dx
      this.y += dy
    }
  }

  hit (link) {
    this.lastSwing = link.swordSwing
    this.life -= link.swordDamage
    if (this.life <= 0) {
      soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
      this.setState(STATE_DYING)
      return
    }
    soundManager.play(resource.getSound(SOUND_ENNEMY_HIT))
    this.knockbackDirection = link.direction
    this.setState(STATE_HURT)
  }

  process (map, link) {
    this.steps++
    if (this.rock?.done) {
      this.rock = undefined
    }

    switch (this.state) {
      case STATE_WAITING:
        if (this.steps >= this.delay) {
          this.setState(STATE_ENTERING)
        }
        break
      case STATE_SPAWNING:
        if (this.steps >= 3 * CLOUD_FRAME_STEPS) {
          this.setState(STATE_WALKING)
          this.turn(map)
        }
        break
      case STATE_ENTERING:
        this.enter(map)
        break
      case STATE_WALKING:
        this.walk(map)
        break
      case STATE_AIMING:
        if (this.steps === AIM_STEPS) {
          this.throwRock(map)
        }
        if (this.steps >= AIM_STEPS + AFTER_THROW_STEPS) {
          this.setState(STATE_WALKING)
        }
        break
      case STATE_HURT:
        this.knockBack(map)
        if (this.steps >= KNOCKBACK_STEPS) {
          this.setState(STATE_WALKING)
        }
        break
      case STATE_DYING:
        if (this.steps >= 3 * DEATH_FRAME_STEPS) {
          this.setState(STATE_DEAD)
        }
        break
    }

    if (!this.isActive) {
      return
    }
    const swordBox = link.getSwordBox()
    if (swordBox && this.state !== STATE_HURT && link.swordSwing !== this.lastSwing && overlaps(swordBox, this.getBox())) {
      this.hit(link)
      return
    }
    if (overlaps(this.getBox(), link.getBodyBox())) {
      link.hurt(CONTACT_DAMAGE, this.getBox())
    }
  }

  draw (context) {
    switch (this.state) {
      case STATE_WAITING:
      case STATE_DEAD:
        return
      case STATE_SPAWNING:
        drawImage(context, resource.getSprite('misc_bomb_blow'), Math.floor(this.steps / CLOUD_FRAME_STEPS), this.x, this.y, this.width, this.height)
        return
      case STATE_DYING:
        drawImage(context, resource.getSprite('death'), Math.floor(this.steps / DEATH_FRAME_STEPS), this.x, this.y, this.width, this.height)
        return
      case STATE_HURT:
        // Flickers while pushed back
        if (Math.floor(this.steps / 2) % 2 === 1) {
          return
        }
    }
    const frame = Math.floor(this.walkedPixels / WALK_FRAME_PIXELS) % 2
    drawImage(context, resource.getSprite(`octorok_${this.color}_${this.direction}_move`), frame, this.x, this.y, this.width, this.height)
  }
}

// Places the screen is free at, far enough from Link (top-left corners of tiles)
function findFreeCells (map, link) {
  const cells = []
  for (let column = 0; column < TILES_PER_LINE; column++) {
    for (let line = 0; line < TILES_PER_COLUMN; line++) {
      const tile = map.getTile(column, line)
      const x = map.x + column * TILE_WIDTH
      const y = map.y + line * TILE_HEIGHT
      const isTransition = tile?.tileTransition && !tile.tileTransition.isEmpty()
      if (!isTransition && !isBlocked(map, inset(x, y, TILE_WIDTH, TILE_HEIGHT, TERRAIN_INSET)) && Math.hypot(x - link.x, y - link.y) >= MIN_SPAWN_DISTANCE) {
        cells.push({ column, line, x, y })
      }
    }
  }

  return cells
}

// Free tiles on the edges of the screen, with the place just outside them and the way in
function findEntries (cells) {
  const entries = []
  for (const cell of cells) {
    if (cell.column === 0) {
      entries.push({ x: cell.x - TILE_WIDTH, y: cell.y, direction: DIRECTION_EAST })
    }
    if (cell.column === TILES_PER_LINE - 1) {
      entries.push({ x: cell.x + TILE_WIDTH, y: cell.y, direction: DIRECTION_WEST })
    }
    if (cell.line === 0) {
      entries.push({ x: cell.x, y: cell.y - TILE_HEIGHT, direction: DIRECTION_SOUTH })
    }
    if (cell.line === TILES_PER_COLUMN - 1) {
      entries.push({ x: cell.x, y: cell.y + TILE_HEIGHT, direction: DIRECTION_NORTH })
    }
  }

  return entries
}

function shuffle (random, values) {
  const shuffled = [...values]
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
  }

  return shuffled
}

// The enemies of a screen, when Link arrives on it. Edge arrivals fall back on clouds on a screen
// with no free edge
export function spawnEnemies (map, link, random = Math.random) {
  const types = map.enemies.flatMap(({ type, count }) => OCTOROKS[type] ? Array(count).fill(type) : [])
  if (types.length === 0) {
    return []
  }
  const cells = shuffle(random, findFreeCells(map, link))
  if (cells.length === 0) {
    return []
  }

  const entries = map.enemySpawn === ENEMY_SPAWN_EDGE ? shuffle(random, findEntries(cells)) : []
  if (entries.length > 0) {
    let delay = 0
    return types.map((type, i) => {
      const entry = entries[i % entries.length]
      delay += randomInt(random, MIN_ENTRY_DELAY, MAX_ENTRY_DELAY)
      return Octorok.fromEdge(type, entry.x, entry.y, entry.direction, delay, random)
    })
  }

  return types.map((type, i) => {
    const cell = cells[i % cells.length]
    return Octorok.inCloud(type, cell.x, cell.y, random)
  })
}

// One game step for the enemies and their rocks of the screen
export function updateEnemies (map, link) {
  for (const enemy of map.activeEnemies) {
    enemy.process(map, link)
  }
  for (const projectile of map.projectiles) {
    projectile.process(map, link)
  }
  map.activeEnemies = map.activeEnemies.filter(enemy => !enemy.isDead)
  map.projectiles = map.projectiles.filter(projectile => !projectile.done)
}

export { Octorok, Rock }
